use ::physical_object::linalg::{Vec3, Mat3, Quat};
use ::physical_object::boundary::{Boundary, Sdf};

// Sdf is the trait every shape implements: a signed distance, plus a
// surface normal that defaults to a central difference of it.
let s = Boundary::Sphere { radius: 0.5 };
let d = s.signed_distance(&Vec3::new(1.0, 0.0, 0.0));
assert!((d - 0.5).abs() < 1e-9);   // 1.0 out from a radius-0.5 sphere

