use ::physical_object::linalg::{Vec3, Mat3, Quat};
use ::physical_object::physical_object::physical_object;
use ::physical_object::boundary::Boundary;
use ::physical_object::collide::{ContactGeometry, contact_geometry};

let a = physical_object::new_rigid(0, 1.0, 0.0, Vec3::new(-0.6, 0.0, 0.0),
    Quat::identity(), Vec3::new(1.0, 0.0, 0.0), Vec3::new(0.0, 0.0, 0.0),
    Mat3::identity(), Mat3::identity(), Boundary::Sphere { radius: 0.5 });
let b = physical_object::new_rigid(1, 1.0, 0.0, Vec3::new(0.6, 0.0, 0.0),
    Quat::identity(), Vec3::new(-1.0, 0.0, 0.0), Vec3::new(0.0, 0.0, 0.0),
    Mat3::identity(), Mat3::identity(), Boundary::Sphere { radius: 0.5 });
let g: Option<ContactGeometry> = contact_geometry(&a, &b, 1e-9);
// the two spheres are 1.2 apart with radii 0.5 each, so they are NOT
// touching yet and the narrow phase says so
assert!(g.is_none());

