use ::physical_object::linalg::{Vec3, Mat3, Quat};
use ::physical_object::physical_object::physical_object;
use ::physical_object::system::PhysicalObjectSystem;
use ::physical_object::collide::resolve_pair;

let mut sys = PhysicalObjectSystem::new(vec![
    physical_object::new_point(0, 1.0, Vec3::new(-1.0, 0.0, 0.0), Vec3::new(1.0, 0.0, 0.0)),
    physical_object::new_point(1, 1.0, Vec3::new(1.0, 0.0, 0.0), Vec3::new(-1.0, 0.0, 0.0)),
], 0.0);
// two POINTS can never collide, so the resolver has nothing to do
let c = resolve_pair(&mut sys, 0, 1, false)?;
assert!(c.is_none());

use ::physical_object::linalg::{Vec3, Mat3, Quat};
use ::physical_object::physical_object::physical_object;
use ::physical_object::system::PhysicalObjectSystem;
use ::physical_object::integrate::run;

let mut sys = PhysicalObjectSystem::new(vec![
    physical_object::new_point(0, 1.0, Vec3::new(0.0, 0.0, 0.0), Vec3::new(1.0, 0.0, 0.0)),
], 0.0);
// every step goes through the pure-Rust SUNDIALS solvers; there is no
// hand-rolled stepper anywhere in the project
let report = run(&mut sys, 1.0, 2)?;
let _ = report;

