use ::special_functions::lanczos::{LanczosResult, Stop};

// what QM2/QM3 STATES return: the k lowest eigenvalues with their vectors
// and the residual that justifies trusting them — an iterative eigensolver
// has no exact stopping point, so the residual is part of the answer
let r = LanczosResult { values: vec![1.0], vectors: vec![vec![1.0]],
                        residuals: vec![1e-8], iterations: 1, stop: Stop::Converged };
assert_eq!(r.values.len(), r.residuals.len());

use ::special_functions::quadrature::integrate_adaptive;

let v = integrate_adaptive(|x: f64| x * x * x, 0.0, 1.0, 1e-10)?;
assert!((v - 0.25).abs() < 1e-10);
// and the honest failure: 1/sqrt(x) on [0,1] is finite but Simpson
// cannot resolve the endpoint, so it ERRORS rather than guessing.
assert!(integrate_adaptive(|x: f64| 1.0 / x.sqrt(), 0.0, 1.0, 1e-10).is_err());

use ::special_functions::quadrature::brent_root;

// cos x = x, bracketed on [0, 1]
let r = brent_root(|x: f64| x.cos() - x, 0.0, 1.0, 1e-12)?;
assert!((r - 0.739085133215).abs() < 1e-9);

use ::special_functions::quadrature::find_roots;

// find_roots CANNOT tell a pole from a root: a pole flips the sign of f
// too, and Brent converges on it. Check f at each value it returns.
let rs = find_roots(|x: f64| x.sin(), 0.1, 7.0, 100, 1e-12)?;
assert!(!rs.is_empty());

use ::quantum::absorber::Ramp;

let ramp = Ramp { width: 15.0, power: 2.0 };
// power 2 is the measured optimum: too steep a ramp is a mirror,
// whether it is real or imaginary
assert_eq!(ramp.power, 2.0);

use ::quantum::absorber::Band;

let band = Band { k_lo: 1.0, k_hi: 4.0, samples: 8 };
