use ::quantum::absorber::Leak;

// the two ways probability escapes an absorber, which trade off against
// each other: too weak and it passes THROUGH, too strong and it reflects
// off the absorber's own leading edge
let leak = Leak { k: 3.0, reflection: 1e-9, leakage: 2e-9, absorbed: 1.0 };
assert!(leak.escaped() > 0.0);

use ::quantum::absorber::Leak;

let leak = Leak { k: 3.0, reflection: 1e-9, leakage: 2e-9, absorbed: 1.0 };
// R + T: everything the absorber failed to swallow
assert!((leak.escaped() - 3e-9).abs() < 1e-18);

use ::quantum::absorber::{Ramp, Band, worst_escape};

let w = worst_escape(Ramp { width: 15.0, power: 2.0 }, 3.0,
                    Band { k_lo: 2.0, k_hi: 4.0, samples: 4 }, 1.0, 1.0)?;
assert!(w >= 0.0);

use ::quantum::absorber::{Ramp, Band, choose_strength};

// the tuning surface has a wide optimum — over an order of magnitude —
// but it is not infinite, so the strength is SEARCHED rather than guessed
let (strength, escape) = choose_strength(Ramp { width: 15.0, power: 2.0 },
                                        Band { k_lo: 2.0, k_hi: 4.0, samples: 4 },
                                        1.0, 1.0)?;
assert!(strength > 0.0 && escape >= 0.0);

